Ul0DC;ITrMA,qBSsMoB;EVw0DrB;EUr0DC;IACC,WAAA;EVu0DF;EUl0DD;IACC,mBAAA;EVo0DA;EUj0DD;IACC,eAAA;EVm0DA;EUh0DD;IACC,YAAA;EVk0DA;EUj0DA;IACC,cAAA;IACA,kBAAA;EVm0DD;EUl0DC;IACC,cAAA;IACA,cAAA;EVo0DF;AACF;AWljEA;EACC,yBZaY;ACuiEb;AWljEC;EACC,wCAAA;AXojEF;AWhjEE;EACC,cZgCK;ACkhER;AW/iEE;EACC,gCAAA;AXijEH;AW7iEC;EACC,yBZuBM;ACwhER;AW5iEC;;;;;;;EAOC,cZaM;ACiiER;AW5iEC;EACC,cZjBW;AC+jEb;AW1iEE;EACC,iBAAA;AX4iEH;AWxiEG;EACC,aAAA;AX0iEJ;AWriEC;;EAEC,qBZjCW;ACwkEb","file":"style.css","sourcesContent":["/*------------------------------------------------\n\tBase Styles\n-------------------------------------------------*/\nbody {\n  font-family: $font-stack;\n  font-weight: 400;\n  font-size: 16px;\n  line-height: 30px;\n  color: $text-color;\n  // parchment rather than white, so the greens and golds sit on something warm\n  background-color: $parchment;\n}\n\na {\n  color: inherit;\n\n  &:hover,\n  &:focus {\n    color: $text-color;\n    text-decoration: none;\n    outline: 0 none;\n  }\n\n  @include transition(all 0.3s ease 0s);\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  color: $title-color;\n  font-family: $open-sans;\n  margin: 0;\n  line-height: 1.3;\n}\n\np {\n  margin-bottom: 20px;\n\n  &:last-child {\n    margin-bottom: 0;\n  }\n}\n\n/*\n * Selection color\n */\n::-moz-selection {\n  background-color: $primary-color;\n  color: $light;\n}\n\n::selection {\n  background-color: $primary-color;\n  color: $light;\n}\n\n/*\n *  Reset bootstrap's default style\n */\n.form-control::-webkit-input-placeholder,\n::-webkit-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-moz-placeholder,\n:-moz-placeholder {\n  /* Firefox 18- */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control::-moz-placeholder,\n::-moz-placeholder {\n  /* Firefox 19+ */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-ms-input-placeholder,\n:-ms-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\nbutton,\ninput,\nselect,\ntextarea,\nlabel {\n  font-weight: 400;\n}\n\n.btn {\n  @include transition(all 0.3s ease 0s);\n\n  &:hover,\n  &:focus,\n  &:active:focus {\n    outline: 0 none;\n  }\n}\n\n.btn-primary {\n  background-color: $primary-color;\n  border: 0;\n  font-family: $open-sans;\n  font-weight: 700;\n  height: 48px;\n  line-height: 50px;\n  padding: 0 42px;\n  text-transform: uppercase;\n\n  &:hover,\n  &:focus,\n  &:active,\n  &:active:focus {\n    background-color: darken($primary-color, 8%);\n  }\n}\n\n.btn-border {\n  border: 1px solid $parchment-line;\n  display: inline-block;\n  padding: 7px;\n}\n\n/*\n *  CSS Helper Class\n */\n.clear {\n\n  &:before,\n  &:after {\n    content: \" \";\n    display: table;\n  }\n\n  &:after {\n    clear: both;\n  }\n}\n\n.pt-table {\n  display: table;\n  width: 100%;\n  @include calc(height, \"100vh - 4px\");\n}\n\n.pt-tablecell {\n  display: table-cell;\n  vertical-align: middle;\n}\n\n.overlay {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 100%;\n  height: 100%;\n}\n\n.relative {\n  position: relative;\n}\n\n.primary,\n.link:hover {\n  color: $primary-color;\n}\n\n.no-gutter {\n  margin-left: 0;\n  margin-right: 0;\n\n  &>[class^=\"col-\"] {\n    padding-left: 0;\n    padding-right: 0;\n  }\n}\n\n.flex {\n  @include flexbox();\n}\n\n.flex-middle {\n  @include align-items(center);\n}\n\n.space-between {\n  @include justify-content(space-between);\n}\n\n.nicescroll-cursors {\n  // muted, so it reads as a scrollbar rather than a gold stripe down the page\n  background: rgba($gold, 0.55) !important;\n  border-radius: 4px !important;\n}","//\n// Typography\n//\n\n$font-stack: \"Libre Baskerville\", serif;\n$open-sans: \"Open Sans\", sans-serif;\n\n//\n// Palette — forest, gold and wood\n//\n// Three families do all the work: deep forest greens for structure, gold for\n// every accent and highlight, and wood browns for warmth underneath. Parchment\n// stands in for white so nothing on the site is ever a cold grey.\n//\n\n// Forest — panels, cards, hexagons, anything structural\n$forest-900: #0b1410; // deepest wells and overlays\n$forest-800: #101c14; // dark page backgrounds\n$forest-700: #17281b; // cards, hexagons, inputs\n$forest-600: #203624; // raised surfaces, chips, bars\n$forest-500: #2d4834; // hairlines and borders on dark\n$moss: #7d9b6a; // muted green, secondary text on dark\n\n// Gold — the accent, used sparingly so it stays precious\n$gold: #c9a227;\n$gold-light: #e6c65f;\n$gold-deep: #8a6d15;\n\n// Wood — warmth, rules, muted body copy\n$wood-900: #2a1d13;\n$wood-700: #4a3524;\n$wood-500: #6b4f36;\n$wood-300: #a08258;\n\n// Parchment — light surfaces, in place of white\n$parchment: #f5efe2;\n$parchment-dim: #eae1cd;\n$parchment-line: #ddd0b4;\n\n//\n// Semantic aliases — everything downstream refers to these\n//\n$primary-color: $gold;\n$light-dark: $forest-700;\n$light: #fbf7ec; // warm white for text and rules on dark\n$text-color: #6f5c44; // body copy on parchment\n$title-color: #1d2f21; // headings on parchment\n$border-color: $parchment-line;\n\n//\n// Hexagon\n//\n$sqrt3: 1.7320508075688772;\n$edgeSize: 100px;\n$hexWidth: $edgeSize * 2;\n$hexHeight: $sqrt3 * $edgeSize;\n\n// Display\n$borderHover: 15px;\n\n// Easing\n$ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);\n$ease-out-quart: cubic-bezier(0.165, 0.84, 0.44, 1);\n","/*------------------------------------------------\n\tBase Styles\n-------------------------------------------------*/\nbody {\n  font-family: \"Libre Baskerville\", serif;\n  font-weight: 400;\n  font-size: 16px;\n  line-height: 30px;\n  color: #6f5c44;\n  background-color: #f5efe2;\n}\n\na {\n  color: inherit;\n}\na:hover, a:focus {\n  color: #6f5c44;\n  text-decoration: none;\n  outline: 0 none;\n}\na {\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  color: #1d2f21;\n  font-family: \"Open Sans\", sans-serif;\n  margin: 0;\n  line-height: 1.3;\n}\n\np {\n  margin-bottom: 20px;\n}\np:last-child {\n  margin-bottom: 0;\n}\n\n/*\n * Selection color\n */\n::-moz-selection {\n  background-color: #c9a227;\n  color: #fbf7ec;\n}\n\n::selection {\n  background-color: #c9a227;\n  color: #fbf7ec;\n}\n\n/*\n *  Reset bootstrap's default style\n */\n.form-control::-webkit-input-placeholder,\n::-webkit-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-moz-placeholder,\n:-moz-placeholder {\n  /* Firefox 18- */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control::-moz-placeholder,\n::-moz-placeholder {\n  /* Firefox 19+ */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-ms-input-placeholder,\n:-ms-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\nbutton,\ninput,\nselect,\ntextarea,\nlabel {\n  font-weight: 400;\n}\n\n.btn {\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n.btn:hover, .btn:focus, .btn:active:focus {\n  outline: 0 none;\n}\n\n.btn-primary {\n  background-color: #c9a227;\n  border: 0;\n  font-family: \"Open Sans\", sans-serif;\n  font-weight: 700;\n  height: 48px;\n  line-height: 50px;\n  padding: 0 42px;\n  text-transform: uppercase;\n}\n.btn-primary:hover, .btn-primary:focus, .btn-primary:active, .btn-primary:active:focus {\n  background-color: rgb(65.4235294118%, 52.7294117647%, 12.6941176471%);\n}\n\n.btn-border {\n  border: 1px solid #ddd0b4;\n  display: inline-block;\n  padding: 7px;\n}\n\n/*\n *  CSS Helper Class\n */\n.clear:before, .clear:after {\n  content: \" \";\n  display: table;\n}\n.clear:after {\n  clear: both;\n}\n\n.pt-table {\n  display: table;\n  width: 100%;\n  height: -webkit-calc(100vh - 4px);\n  height: -moz-calc(100vh - 4px);\n  height: calc(100vh - 4px);\n}\n\n.pt-tablecell {\n  display: table-cell;\n  vertical-align: middle;\n}\n\n.overlay {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 100%;\n  height: 100%;\n}\n\n.relative {\n  position: relative;\n}\n\n.primary,\n.link:hover {\n  color: #c9a227;\n}\n\n.no-gutter {\n  margin-left: 0;\n  margin-right: 0;\n}\n.no-gutter > [class^=col-] {\n  padding-left: 0;\n  padding-right: 0;\n}\n\n.flex {\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -moz-flex;\n  display: -ms-flexbox;\n  display: flex;\n}\n\n.flex-middle {\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  align-items: center;\n}\n\n.space-between {\n  -webkit-box-pack: justify;\n  -ms-flex-pack: justify;\n  -webkit-justify-content: space-between;\n  -moz-justify-content: space-between;\n  justify-content: space-between;\n}\n\n.nicescroll-cursors {\n  background: rgba(201, 162, 39, 0.55) !important;\n  border-radius: 4px !important;\n}\n\n.preloader {\n  bottom: 0;\n  left: 0;\n  position: fixed;\n  right: 0;\n  top: 0;\n  z-index: 1000;\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -moz-flex;\n  display: -ms-flexbox;\n  display: flex;\n}\n.preloader.active.hidden {\n  display: none;\n}\n\n.loading-mask {\n  background-color: #c9a227;\n  height: 100%;\n  left: 0;\n  position: absolute;\n  top: 0;\n  width: 20%;\n  -webkit-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  -moz-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  -o-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n}\n.loading-mask:nth-child(2) {\n  left: 20%;\n  -webkit-transition-delay: 0.1s;\n  -moz-transition-delay: 0.1s;\n  -o-transition-delay: 0.1s;\n  transition-delay: 0.1s;\n}\n.loading-mask:nth-child(3) {\n  left: 40%;\n  -webkit-transition-delay: 0.2s;\n  -moz-transition-delay: 0.2s;\n  -o-transition-delay: 0.2s;\n  transition-delay: 0.2s;\n}\n.loading-mask:nth-child(4) {\n  left: 60%;\n  -webkit-transition-delay: 0.3s;\n  -moz-transition-delay: 0.3s;\n  -o-transition-delay: 0.3s;\n  transition-delay: 0.3s;\n}\n.loading-mask:nth-child(5) {\n  left: 80%;\n  -webkit-transition-delay: 0.4s;\n  -moz-transition-delay: 0.4s;\n  -o-transition-delay: 0.4s;\n  transition-delay: 0.4s;\n}\n\n.preloader.active.done {\n  z-index: 0;\n}\n.preloader.active .loading-mask {\n  width: 0;\n}\n\n/*------------------------------------------------\n\tStart Styling\n-------------------------------------------------*/\n.site-wrapper {\n  border-top: 4px solid #c9a227;\n}\n\n.page-close {\n  font-size: 30px;\n  position: absolute;\n  right: 30px;\n  top: 30px;\n  z-index: 100;\n}\n\n.page-title {\n  margin-bottom: 75px;\n}\n.page-title img {\n  margin-bottom: 20px;\n}\n.page-title h2 {\n  font-size: 68px;\n  margin-bottom: 25px;\n  position: relative;\n  z-index: 0;\n  font-weight: 900;\n  text-transform: uppercase;\n}\n.page-title p {\n  font-size: 16px;\n}\n.page-title .title-bg {\n  color: rgba(23, 40, 27, 0.07);\n  font-size: 158px;\n  left: 50%;\n  letter-spacing: 10px;\n  line-height: 0.7;\n  position: absolute;\n  top: 50%;\n  z-index: -1;\n  -webkit-transform: translate(-50%, -50%);\n  -moz-transform: translate(-50%, -50%);\n  -ms-transform: translate(-50%, -50%);\n  -o-transform: translate(-50%, -50%);\n  transform: translate(-50%, -50%);\n}\n\n.section-title {\n  margin-bottom: 20px;\n  overflow: hidden;\n}\n.section-title h3 {\n  display: inline-block;\n  position: relative;\n}\n.section-title h3::before, .section-title h3::after {\n  content: \"\";\n  height: 2px;\n  position: absolute;\n  bottom: 8px;\n  left: -webkit-calc(100% + 14px);\n  left: -moz-calc(100% + 14px);\n  left: calc(100% + 14px);\n}\n.section-title h3::before {\n  background-color: #17281b;\n  width: 96px;\n  bottom: 14px;\n}\n.section-title h3::after {\n  background-color: #c9a227;\n  width: 73px;\n}\n.section-title.light h3 {\n  color: #fbf7ec;\n}\n.section-title.light h3::before {\n  background-color: #fbf7ec;\n}\n\n.page-nav {\n  bottom: 40px;\n  left: 0;\n  position: absolute;\n  right: 0;\n}\n.page-nav span {\n  font-family: \"Open Sans\", sans-serif;\n  font-size: 14px;\n  font-weight: 500;\n  line-height: 1.3;\n  text-transform: uppercase;\n}\n\n/*------------------------------------------------\n    Home Page\n-------------------------------------------------*/\n.page-home {\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  vertical-align: middle;\n}\n.page-home .overlay {\n  background-color: rgba(251, 247, 236, 0.93);\n}\n\n/* End of container */\n.hexagon-item {\n  cursor: pointer;\n  width: 200px;\n  height: 173.2050807569px;\n  float: left;\n  margin-left: -29px;\n  z-index: 0;\n  position: relative;\n  -webkit-transform: rotate(30deg);\n  -moz-transform: rotate(30deg);\n  -ms-transform: rotate(30deg);\n  -o-transform: rotate(30deg);\n  transform: rotate(30deg);\n}\n.hexagon-item:first-child {\n  margin-left: 0;\n}\n.hexagon-item:hover {\n  z-index: 1;\n}\n.hexagon-item:hover .hex-item:last-child {\n  opacity: 1;\n  -webkit-transform: scale(1.3);\n  -moz-transform: scale(1.3);\n  -ms-transform: scale(1.3);\n  -o-transform: scale(1.3);\n  transform: scale(1.3);\n}\n.hexagon-item:hover .hex-item:first-child {\n  opacity: 1;\n  -webkit-transform: scale(1.2);\n  -moz-transform: scale(1.2);\n  -ms-transform: scale(1.2);\n  -o-transform: scale(1.2);\n  transform: scale(1.2);\n}\n.hexagon-item:hover .hex-item:first-child div:before,\n.hexagon-item:hover .hex-item:first-child div:after {\n  height: 15px;\n}\n.hexagon-item:hover .hex-item div::before,\n.hexagon-item:hover .hex-item div::after {\n  background-color: #c9a227;\n}\n.hexagon-item:hover .hex-content svg {\n  -webkit-transform: scale(0.97);\n  -moz-transform: scale(0.97);\n  -ms-transform: scale(0.97);\n  -o-transform: scale(0.97);\n  transform: scale(0.97);\n}\n\n.page-home .hexagon-item:nth-child(n+5) {\n  -webkit-transform: rotate(30deg) translate(87px, -80px);\n  -moz-transform: rotate(30deg) translate(87px, -80px);\n  -ms-transform: rotate(30deg) translate(87px, -80px);\n  -o-transform: rotate(30deg) translate(87px, -80px);\n  transform: rotate(30deg) translate(87px, -80px);\n}\n\n.hex-item {\n  position: absolute;\n  top: 0;\n  left: 50px;\n  width: 100px;\n  height: 173.2050807569px;\n}\n.hex-item:first-child {\n  z-index: 0;\n  -webkit-transform: scale(0.9);\n  -moz-transform: scale(0.9);\n  -ms-transform: scale(0.9);\n  -o-transform: scale(0.9);\n  transform: scale(0.9);\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n}\n.hex-item:last-child {\n  transition: all 0.3s cubic-bezier(0.19, 1, 0.22, 1);\n  z-index: 1;\n}\n.hex-item div {\n  box-sizing: border-box;\n  position: absolute;\n  top: 0;\n  width: 100px;\n  height: 173.2050807569px;\n  -webkit-transform-origin: center center;\n  -moz-transform-origin: center center;\n  -ms-transform-origin: center center;\n  -o-transform-origin: center center;\n  transform-origin: center center;\n}\n.hex-item div::before, .hex-item div::after {\n  background-color: #17281b;\n  content: \"\";\n  position: absolute;\n  width: 100%;\n  height: 3px;\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n}\n.hex-item div:before {\n  top: 0;\n}\n.hex-item div:after {\n  bottom: 0;\n}\n.hex-item div:nth-child(1) {\n  -webkit-transform: rotate(0deg);\n  -moz-transform: rotate(0deg);\n  -ms-transform: rotate(0deg);\n  -o-transform: rotate(0deg);\n  transform: rotate(0deg);\n}\n.hex-item div:nth-child(2) {\n  -webkit-transform: rotate(60deg);\n  -moz-transform: rotate(60deg);\n  -ms-transform: rotate(60deg);\n  -o-transform: rotate(60deg);\n  transform: rotate(60deg);\n}\n.hex-item div:nth-child(3) {\n  -webkit-transform: rotate(120deg);\n  -moz-transform: rotate(120deg);\n  -ms-transform: rotate(120deg);\n  -o-transform: rotate(120deg);\n  transform: rotate(120deg);\n}\n\n.hex-content {\n  color: #fbf7ec;\n  display: block;\n  height: 180px;\n  margin: 0 auto;\n  position: relative;\n  text-align: center;\n  transform: rotate(-30deg);\n  width: 156px;\n}\n.hex-content .hex-content-inner {\n  left: 50%;\n  margin: -3px 0 0 2px;\n  position: absolute;\n  top: 50%;\n  -webkit-transform: translate(-50%, -50%);\n  -moz-transform: translate(-50%, -50%);\n  -ms-transform: translate(-50%, -50%);\n  -o-transform: translate(-50%, -50%);\n  transform: translate(-50%, -50%);\n}\n.hex-content .icon {\n  display: block;\n  font-size: 36px;\n  line-height: 30px;\n  margin-bottom: 11px;\n}\n.hex-content .title {\n  display: block;\n  font-family: \"Open Sans\", sans-serif;\n  font-size: 14px;\n  letter-spacing: 1px;\n  line-height: 24px;\n  text-transform: uppercase;\n}\n.hex-content svg {\n  left: -7px;\n  position: absolute;\n  top: -13px;\n  transform: scale(0.87);\n  z-index: -1;\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n}\n.hex-content:hover {\n  color: #fbf7ec;\n}\n\n/*------------------------------------------------\n    Welcome Page\n-------------------------------------------------*/\n.author-image-large {\n  position: absolute;\n  right: 0;\n  top: 0;\n}\n.author-image-large img {\n  height: -webkit-calc(100vh - 4px);\n  height: -moz-calc(100vh - 4px);\n  height: calc(100vh - 4px);\n}\n\n/*------------------------------------------------\n    About Page\n-------------------------------------------------*/\n.about-author {\n  margin-bottom: 23px;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  -webkit-align-items: center;\n  -moz-align-items: center